 box.innerHTML='<h3>📋 오늘의 주문</h3>'+g.list.map((m,i)=>'<div class="goal-row'+(m.claimed?' done':'')+'"><span>'+m.text+'</span><progress max="'+m.goal+'" value="'+m.progress+'"></progress><small>'+m.progress+'/'+m.goal+'</small>'+(m.claimed?'<b>✓</b>':m.progress>=m.goal?'<button type="button" data-goal="'+i+'">🪙 '+m.reward+' 받기</button>':'<small>🪙 '+m.reward+'</small>')+'</div>').join('')
