  +'<h3>📖 요리 도감</h3><div class="goal-row'+(book.claimed?' done':'')+'"><span>모든 요리 한 번씩 완성하기</span><progress max="'+book.total+'" value="'+book.done+'"></progress><small>'+book.done+'/'+book.total+'</small>'+(book.claimed?'<b>👑</b>':book.done===book.total&&book.total?'<button type="button" data-book>🪙 '+BOOK_REWARD+' 받기</button>':'<small>👑 '+BOOK_REWARD+'</small>')+'</div>';
